export const RAW_FRAMEWORKS: SessionFramework[] = SPECS.map((s) => {
  const stageSequence = s.stages.filter((x) => (SESSION_STAGE_IDS as readonly string[]).includes(x)) as (typeof SESSION_STAGE_IDS)[number][];
  const componentSequence = s.components && s.components.length
    ? s.components
    : stageSequence.map((st) => stageToComponent(st));
  const outcomes = s.outcomes && s.outcomes.length ? s.outcomes : DEFAULT_OUTCOMES(s.id, s.goal);
  const adaptations = s.adaptations && s.adaptations.length ? s.adaptations : DEFAULT_ADAPTATIONS;
  const techniques = s.techs.filter((t) => TECHNIQUE_IDS.has(t));
  return {
    id: s.id,
    version: "1.0.0",
    name: s.name,
    category: s.category,
    tradition: s.tradition,
    primaryGoal: s.goal,
    description: s.desc || s.goal,
    durationMinutes: { min: s.dur[0], default: s.dur[1], max: s.dur[2] },
    difficulty: s.diff,
    deliveryModes: s.modes,
    compatibleTechniques: techniques.length ? techniques : [s.techs[0] || "focused_attention"],
    stageSequence,
    componentSequence,
    outcomes,
    adaptations,
    completionCriteria: [
      { id: `${s.id}_practice_completed`, type: "stage_completed", stageId: "core_experience" },
      { id: `${s.id}_closure_shown`, type: "closure_shown" },
    ],
    safety: {
      notTreatment: true,
      stopSignals: ["dizziness", "distress", "discomfort", "overwhelm"],
      avoidWhen: ["acute crisis", "severe distress"],
      professionalGuidanceRecommended: false,
    },
    accessibility: {
      reducedMotionSupported: true,
      captionsSupported: true,
      screenReaderSupported: true,
      alternatives: ["shorter duration", "silent mode", "text-only prompts"],
    },
    provenance: {
      sourceKind: "internal_design",
      sourceLabel: "ConsciousOS session framework library",
      reviewedAt: REVIEWED_AT,
      notes: "Product-designed framework; not a clinically validated protocol.",
    },
  };
});

function stageToComponent(stage: (typeof SESSION_STAGE_IDS)[number]): (typeof SESSION_COMPONENT_IDS)[number] {
  switch (stage) {
    case "arrival": return "arrival";
    case "baseline": return "check_in";
    case "orientation": return "orientation";
    case "settling": return "settling";
    case "induction": return "anchor";
    case "core_experience": return "core_practice";
    case "deepening": return "variation";
    case "observation": return "reflection";
    case "insight": return "insight";
    case "application": return "application";
    case "integration": return "reflection";
    case "reflection": return "reflection";
    case "adaptation": return "closure";
    default: return "closure";
  }
}

export const FRAMEWORK_CATALOG: SessionFramework[] = frameworkCatalogSchema.parse(RAW_FRAMEWORKS);
export const TECHNIQUE_CATALOG: FrameworkTechnique[] = techniqueCatalogSchema.parse(FRAMEWORK_TECHNIQUES);
export const SESSION_FRAMEWORKS = FRAMEWORK_CATALOG;
export const FRAMEWORKS = FRAMEWORK_CATALOG;

